    (authority_key, authority_account.clone()),
];
let r_legit = env.baseline("init legitimo com authority assinando", &ix_legit, &contas_legit);

let config_pos = after(&r_legit, &config_key).clone();

let metas_ataque = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority_key, false),
];
let ix_ataque = env.raw_ix(&[0u8], metas_ataque);
let contas_ataque = vec![
    (config_key, config_pos),
    (authority_key, authority_account),
];
let r = env.attack("init sem assinatura da authority", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &config_key).data();
    let autoridade_gravada = read_pubkey(dados, 8);
    env.effect(
